import{_ as a,o as t,c as n,O as r}from"./app.a7aece7e.js";const u='{"title":"Overview","description":"","frontmatter":{},"headers":[{"level":2,"title":"Items and Types","slug":"items-and-types"},{"level":2,"title":"Monitors","slug":"monitors"},{"level":2,"title":"Connectors","slug":"connectors"},{"level":2,"title":"Drag Sources and Drop Targets","slug":"drag-sources-and-drop-targets"},{"level":2,"title":"Backend","slug":"backend"},{"level":2,"title":"in conclusion","slug":"in-conclusion"}],"relativePath":"en/guide/overview.md"}',o={};function d(s,e,c,i,l,p){return t(),n("div",null,e[0]||(e[0]=[r('<p><code>drop</code> is a ref function, it can be called in many ways, we usually use it by using <code>v-bind:ref=&quot;drop&quot;</code> directly on the DOM node, it will tell DnD that the DOM is a valid drop node, and its hover and drop events are handled by the dnd backend.</p><h2 id="drag-sources-and-drop-targets" tabindex="-1">Drag Sources and Drop Targets <a class="header-anchor" href="#drag-sources-and-drop-targets" aria-hidden="true">#</a></h2><p>We use the drag source <code>dragSource</code> to represent the dragged element</p><p>We use the drop target <code>drop</code> to indicate that the target receives the dragged element</p><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-hidden="true">#</a></h2><p>Backend abstracts away browser differences and handles native DOM events. All Backend does is translate DOM events into internal Redux actions that React DnD can handle.</p><p>Benefiting from the design of React DnD, we can also directly adopt its <a href="https://www.npmjs.com/package/react-dnd-html5-backend" target="_blank" rel="noopener noreferrer">HTML5 Backend</a> , [Touch Backend](<a href="https://www" target="_blank" rel="noopener noreferrer">https://www</a> .npmjs.com/package/react-dnd-touch-backend) and <a href="https://www.npmjs.com/package/react-dnd-test-backend" target="_blank" rel="noopener noreferrer">Test Backend</a>, and even some custom backends</p><h2 id="in-conclusion" tabindex="-1">in conclusion <a class="header-anchor" href="#in-conclusion" aria-hidden="true">#</a></h2><p>We have described some of the core concepts of React DnD. For a more detailed introduction, please refer to <a href="https://react-dnd.github.io/react-dnd/docs/overview" target="_blank" rel="noopener noreferrer">React DnD Overview</a></p>',9)]))}var g=a(o,[["render",d]]);export{u as __pageData,g as default};
